create table app_users (id bigint generated by default as identity primary key, email varchar(255) not null unique, password varchar(255) not null, role varchar(30) not null, version bigint);
create table product (id bigint generated by default as identity primary key, sku varchar(255) not null unique, name varchar(255) not null, category varchar(255), price numeric(19,2) not null, active boolean not null, version bigint);
create table stock (id bigint generated by default as identity primary key, product_id bigint not null, location varchar(30) not null, available integer not null, reserved integer not null, version bigint, unique(product_id,location));
create table reservation (id bigint generated by default as identity primary key, order_id bigint not null, product_id bigint not null, location varchar(30) not null, quantity integer not null, expires_at timestamp with time zone, state varchar(30));
create table shopping_cart (id bigint generated by default as identity primary key, customer_id bigint not null, channel varchar(30), version bigint);
create table cart_item (id bigint generated by default as identity primary key, cart_id bigint not null, product_id bigint not null, quantity integer not null, foreign key(cart_id) references shopping_cart(id));
create table purchase_orders (id bigint generated by default as identity primary key, customer_id bigint not null, channel varchar(30), status varchar(30), total numeric(19,2), version bigint);
create table payment (id bigint generated by default as identity primary key, order_id bigint not null, idempotency_key varchar(255) not null, status varchar(30), amount numeric(19,2), unique(order_id,idempotency_key));
create table idempotency_record (idempotency_key varchar(255) primary key, request_hash varchar(255) not null, response_status integer not null, response_body clob);
